pub unsafe fn basic_open_close_interaction(mut player: Gc<terraria::player::Player>, mut x: i32, mut y: i32, mut id: i32) {
    terraria::player::close_sign(player.ptr(), false);
    let mut interactingPlayer: i32 = 0;
    if (!((*terraria::main::s()).net_mode == 1))
    {
        (*terraria::main::s()).stack_split = 600;
        terraria::player::gamepad_enable_grapple_cooldown(player.ptr());
        if terraria::data_structures::tile_entity::is_occupied(id, core::ptr::addr_of_mut!(interactingPlayer))
        {
            if (interactingPlayer == (*(player.ptr() as *mut terraria::entity::Entity)).who_am_i)
            {
                let _ = terraria::audio::sound_engine::play_sound__int_int_int_int_float_float(11, (-1), (-1), 1, 1.0f32, 0.0f32);
                terraria::data_structures::player_interaction_anchor::clear(core::ptr::addr_of_mut!((*player.ptr()).tile_entity_anchor));
            }
        }
        else
        {
            terraria::data_structures::tile_entity::set_interaction_anchor(player, x, y, id);
        }
        return;
    }
    (*terraria::main::s()).stack_split = 600;
    terraria::player::gamepad_enable_grapple_cooldown(player.ptr());
    if terraria::data_structures::tile_entity::is_occupied(id, core::ptr::addr_of_mut!(interactingPlayer))
    {
        if (interactingPlayer == (*(player.ptr() as *mut terraria::entity::Entity)).who_am_i)
        {
            let _ = terraria::audio::sound_engine::play_sound__int_int_int_int_float_float(11, (-1), (-1), 1, 1.0f32, 0.0f32);
            terraria::data_structures::player_interaction_anchor::clear(core::ptr::addr_of_mut!((*player.ptr()).tile_entity_anchor));
            terraria::net_message::send_data(122, (-1), (-1), Gc::<terraria::localization::network_text::NetworkText>::NULL, (-1), ((*terraria::main::s()).my_player as f32), 0.0f32, 0.0f32, 0, 0, 0);
        }
    }
    else
    {
        terraria::net_message::send_data(122, (-1), (-1), Gc::<terraria::localization::network_text::NetworkText>::NULL, id, ((*terraria::main::s()).my_player as f32), 0.0f32, 0.0f32, 0, 0, 0);
    }
}

/// `TileEntity.SetInteractionAnchor(Player, int, int, int)` (TileEntity.cs:289)
pub unsafe fn set_interaction_anchor(mut player: Gc<terraria::player::Player>, mut x: i32, mut y: i32, mut id: i32) {
    (*player.ptr()).chest = (-1);
    terraria::player::set_talk_npc__int_2(player.ptr(), (-1));
    if ((*(player.ptr() as *mut terraria::entity::Entity)).who_am_i == (*terraria::main::s()).my_player)
    {
        let mut num: bool = ((*player.ptr()).tile_entity_anchor.interact_entity_id == (-1));
        terraria::ui::ingame_ui_windows::close_all(true);
        (*terraria::main::s()).player_inventory = true;
        (*terraria::main::s()).pips_use_grid = false;
        if (*terraria::game_input::player_input::s()).grapple_and_interact_are_shared
        {
            terraria::game_input::triggers_set::set_grapple((*(*terraria::game_input::player_input::s()).triggers.ptr()).just_pressed.ptr(), false);
        }
        if (!num)
        {
            let _ = terraria::audio::sound_engine::play_sound__int_int_int_int_float_float(12, (-1), (-1), 1, 1.0f32, 0.0f32);
        }
        else
        {
            let _ = terraria::audio::sound_engine::play_sound__int_int_int_int_float_float(10, (-1), (-1), 1, 1.0f32, 0.0f32);
        }
    }
    terraria::data_structures::player_interaction_anchor::set(core::ptr::addr_of_mut!((*player.ptr()).tile_entity_anchor), id, x, y);
}

